#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/control/shared_capabilities/shared_capabilities.hpp"
#include "gui_forms/types.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// MenuStrip's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/menu_strip.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// Whether an ampersand in an item's text marks its access key (Windows Forms' UseMnemonic; default true).
template <typename Declaring>
struct MenuStripUseMnemonicCapability {
    PropertyCell<bool, MenuStripUseMnemonicCapability<Declaring>> use_mnemonic{true};

    static void assign(MenuStripUseMnemonicCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.use_mnemonic), incoming);
        if (!capability.use_mnemonic.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.use_mnemonic));
    }
};

// The horizontal padding on each side of a top-level item's text, 4 to 64 (default 11). A value outside that range throws std::invalid_argument and changes nothing; a change closes an open menu.
template <typename Declaring>
struct MenuStripItemPaddingCapability {
    PropertyCell<double, MenuStripItemPaddingCapability<Declaring>> item_padding{11.0};

    static void assign(MenuStripItemPaddingCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.item_padding), incoming);
        if (!capability.item_padding.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.item_padding));
    }
};

// Whether the strip takes part in merging, as source or target (Windows Forms' AllowMerge; merge_strips). On by default.
template <typename Declaring>
struct MenuStripAllowMergeCapability {
    PropertyCell<bool, MenuStripAllowMergeCapability<Declaring>> allow_merge{true};

    static void assign(MenuStripAllowMergeCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.allow_merge), incoming);
        if (!capability.allow_merge.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.allow_merge));
    }
};

// The stable ID of the top-level item shown as selected, or empty for none; an ID that names no visible top-level item throws std::out_of_range. set_items clears it. A view onto the strip's selection.
template <typename Declaring>
struct MenuStripSelectedItemIdCapability {
    PropertyView<std::string, MenuStripSelectedItemIdCapability<Declaring>> selected_item_id;

    static void assign(MenuStripSelectedItemIdCapability& capability, std::string incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.selected_item_id), std::move(incoming));
    }

    static std::string read(const MenuStripSelectedItemIdCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        std::string current = control.read_view(capability.selected_item_id);
        return current;
    }
};

// Every MenuStrip capability, in the order the declaring class takes them.
template <typename Declaring>
struct MenuStripCapabilities : public MenuStripUseMnemonicCapability<Declaring>,
                               public MenuStripItemPaddingCapability<Declaring>,
                               public FontCapability<Declaring>,
                               public MenuStripAllowMergeCapability<Declaring>,
                               public MenuStripSelectedItemIdCapability<Declaring> {
    MenuStripCapabilities() : FontCapability<Declaring>(FontSpec{FontRole::control, 10.5, 400, false, 0.12}) {}
};

} // namespace gui_forms
